)

data class Ten05(
    val f1: ByteArray,
    val f2: String,
    val f3: Boolean,
    val f4: Byte,
    val f5: Short,
    val f6: Int,
    val f7: Long,
    val f8: UByte,
    val f9: UShort,
    val f10: UInt,
