fun writeTen05(w: SpecWriter, obj: Ten05) {
    w.beginObject(10)
    w.writeField("f1"); w.writeBytes(obj.f1)
    w.writeField("f2"); w.writeString(obj.f2)
    w.writeField("f3"); w.writeBool(obj.f3)
    w.writeField("f4"); w.writeInt32(obj.f4.toInt())
    w.writeField("f5"); w.writeInt32(obj.f5.toInt())
