    w.writeField("f7"); w.writeInt64(obj.f7)
    w.writeField("f8"); w.writeUint32(obj.f8.toUInt())
    w.writeField("f9"); w.writeUint32(obj.f9.toUInt())
    w.writeField("f10"); w.writeUint32(obj.f10)
    w.endObject()
}

